function secureRandomIndex(max){if(max<=1)return 0;const limit=0x100000000-(0x100000000%max),buffer=new Uint32Array(1);do{crypto.getRandomValues(buffer)}while(buffer[0]>=limit);return buffer[0]%max}
function shuffle(list){const result=[...list];for(let index=result.length-1;index>0;index--){const swapIndex=secureRandomIndex(index+1);[result[index],result[swapIndex]]=[result[swapIndex],result[index]]}return result}
function uniqueQuestionPool(pool){const ids=new Set(),stems=new Set();return pool.filter(item=>{const stem=`${item.question}|${Array.isArray(item.options)?item.options.join("|"):""}`.replace(/\s+/g,"").toLowerCase();if(ids.has(item.id)||stems.has(stem))return false;ids.add(item.id);stems.add(stem);return true})}
function diverseQuestionQueue(pool,count=Infinity){const groups=new Map();shuffle(pool).forEach(item=>{const key=`${item.unit}|${item.knowledgePoint}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item)});const queues=shuffle([...groups.values()]),result=[];while(queues.some(group=>group.length)&&result.length<count){for(const group of queues){if(group.length&&result.length<count)result.push(group.shift())}}return result}
function challengePool(){return uniqueQuestionPool(state.questions.filter(item=>isChallengeQuestion(item)&&matchesDifficulty(item,state.difficulty)&&(!state.unit||item.unit===state.unit)&&matchesQuestionSource(item,state.sourceFilter)))}
