async function fetchQuestionData(url,signal){const requestUrl=new URL(url,document.baseURI);let lastError;for(let attempt=0;attempt<4;attempt++){try{const response=await fetch(requestUrl.href,{signal});if(!response.ok)throw new Error(`HTTP ${response.status}：${requestUrl.pathname}`);return await response.json()}catch(error){lastError=error;if(typeof caches!=="undefined"){try{const cached=await caches.match(requestUrl.href,{ignoreSearch:true});if(cached?.ok)return await cached.json()}catch{}}if(error.name==="AbortError")throw error;if(attempt===3)throw error instanceof TypeError?new Error(`網路連線失敗，請確認網路後重試（${requestUrl.pathname}）`):new Error(`${error.message}（${requestUrl.pathname}）`);await new Promise(resolve=>setTimeout(resolve,350*2**attempt))}}throw lastError}
async function loadSubject(){elements.loading.classList.remove("hidden");elements.loading.textContent="正在載入題庫…";elements.quiz.classList.add("hidden");elements.empty.classList.add("hidden");elements.startChallenge.disabled=false;elements.startChallenge.textContent="載入中，點此開始挑戰";elements.startChallenge.dataset.action="loading";elements.challengeAvailability.textContent="正在準備本回合題目；現在點擊會在載入完成後自動開始";try{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),30000);let results;try{results=await Promise.allSettled([fetchQuestionData(`./data/${FILES[state.subject]}.json?v=${SUBJECT_DATA_VERSION}`,controller.signal),fetchQuestionData(`./data/mission-questions.json?v=${QUESTION_DATA_VERSION}`,controller.signal)])}finally{clearTimeout(timeout)}const baseResult=results[0],missionResult=results[1];if(baseResult.status==="rejected")throw baseResult.reason;const baseQuestions=baseResult.value,missionQuestions=missionResult.status==="fulfilled"?missionResult.value:[];if(!Array.isArray(baseQuestions)||!Array.isArray(missionQuestions))throw new Error("題庫格式無法辨識");state.questions=[...baseQuestions,...missionQuestions.filter(item=>item.subject===state.subject)];state.questionBag=[];renderUnits();nextQuestion();syncChallengeButton();if(missionResult.status==="rejected")elements.challengeAvailability.textContent="一般題庫已載入；歷屆真題連線暫時中斷，請確認網路後重新整理。";if(queuedChallengeStart){queuedChallengeStart=false;startChallenge()}}catch(error){queuedChallengeStart=false;state.questions=[];state.questionBag=[];elements.loading.textContent=`題庫載入失敗：${error.name==="AbortError"?"等待逾時，請檢查網路":error instanceof TypeError?"網路連線中斷，請確認網路後重試":error.message}`;elements.challengeAvailability.textContent="題庫沒有載入完成。請點擊按鈕重新載入";elements.startChallenge.disabled=false;elements.startChallenge.textContent="重新載入題庫";elements.startChallenge.dataset.action="retry"}}
function isUsableQuestion(item){if(!item||typeof item.question!=="string"||!item.question.trim())return false;if(Array.isArray(item.responseParts)&&item.responseParts.length)return item.responseParts.every(part=>part&&((Array.isArray(part.acceptableAnswers)&&part.acceptableAnswers.length)||part.answer!==undefined));return Array.isArray(item.options)&&item.options.length===4&&Number.isInteger(item.answer)&&item.answer>=0&&item.answer<item.options.length}
function filteredPool(){let pool=state.questions.filter(item=>isUsableQuestion(item)&&matchesDifficulty(item,state.difficulty)&&(!state.unit||item.unit===state.unit)&&matchesQuestionSource(item,state.sourceFilter));if(state.wrongMode){const ids=new Set(state.wrongs);pool=pool.filter(item=>ids.has(item.id))}return pool}
