function renderQuestionPrompt(element,content){const lines=content.split("\n");const fragment=document.createDocumentFragment();const isTableSeparator=line=>/^\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?$/.test(line.trim());const cells=line=>line.trim().replace(/^\|/,"").replace(/\|$/,"").split("|").map(cell=>cell.trim());const isTableStart=index=>{if(!lines[index]?.trim().startsWith("|")||!lines[index+1]?.trim().startsWith("|"))return false;let next=index+1;if(isTableSeparator(lines[next]))next++;return Boolean(lines[next]?.trim().startsWith("|")&&cells(lines[index]).length===cells(lines[next]).length)};for(let index=0;index<lines.length;){if(isTableStart(index)){const tableLines=[lines[index]];index++;while(index<lines.length&&lines[index].trim().startsWith("|")){if(!isTableSeparator(lines[index]))tableLines.push(lines[index]);index++}const wrapper=document.createElement("div");wrapper.className="question-table-wrap";const table=document.createElement("table");table.className="question-data-table";const head=document.createElement("thead");const headerRow=document.createElement("tr");for(const value of cells(tableLines[0])){const cell=document.createElement("th");cell.scope="col";cell.textContent=value;headerRow.append(cell)}head.append(headerRow);table.append(head);const body=document.createElement("tbody");for(const row of tableLines.slice(1)){const tr=document.createElement("tr");for(const value of cells(row)){const cell=document.createElement("td");cell.textContent=value;tr.append(cell)}body.append(tr)}table.append(body);wrapper.append(table);fragment.append(wrapper);continue}const paragraph=[];while(index<lines.length&&!isTableStart(index)){paragraph.push(lines[index]);index++}for(let lineIndex=0;lineIndex<paragraph.length;lineIndex++){if(lineIndex)fragment.append(document.createElement("br"));fragment.append(document.createTextNode(paragraph[lineIndex]))}}element.replaceChildren(fragment)}
function renderQuestion(){const item=state.current;const lessonLabel=state.lesson.active?`第 ${state.lesson.answered+1} / ${LESSON_SIZE} 題｜`:"";const detail=item.sourceType==="官方歷屆真題"?`${item.source?.year||""} 年會考${item.source?.section?`｜${item.source.section}`:""}｜第 ${item.source?.questionNumber||""} 題${item.source?.editorialNote?"｜選項依原文校訂":""}`:item.sourceType==="依114年官方真題能力指標原創"?"會考類題":`${item.gradeSemester}｜${item.unit}｜${item.knowledgePoint}`;elements.meta.textContent=`${lessonLabel}${item.subject}｜${detail}｜${item.difficulty}${state.wrongMode?"｜錯題複習":""}`;const images=item.questionImages?.length?item.questionImages:item.questionImage?[item.questionImage]:[];const showFigure=Boolean(item.requiresImage&&images.length);elements.questionFigure.classList.toggle("hidden",!showFigure);elements.questionImages.innerHTML=showFigure?images.map((src,index)=>renderQuestionImage(src,item.imageAlt||(item.requiresContext?`本題閱讀材料第 ${index+1} 頁`:"本題作答所需圖表"),index===0?item.imageCrop:null)).join(""):"";elements.questionCaption.textContent=item.requiresContext?"本題閱讀材料・請先閱讀後再作答":"本題作答所需圖表";renderQuestionPrompt(elements.question,item.question);elements.feedback.className="feedback hidden";elements.options.innerHTML=item.responseParts?.length?item.responseParts.map((part,index)=>`<label class="constructed-part"><span>${escapeHtml(part.label)} ${escapeHtml(part.prompt||"")}</span><input type="text" data-response-part="${index}" aria-label="${escapeHtml(part.label)}作答" placeholder="輸入答案" autocomplete="off" spellcheck="false"></label>`).join(""):item.options.map((option,index)=>{const letter=String.fromCharCode(65+index);return `<button class="option" data-index="${index}" type="button">${item.optionsInImage?"":`<b>${letter}</b>　`}${escapeHtml(item.optionsInImage?letter:option)}</button>`}).join("");elements.options.querySelectorAll("button").forEach(button=>button.addEventListener("click",()=>{if(state.answered)return;state.selected=Number(button.dataset.index);elements.options.querySelectorAll("button").forEach(option=>option.classList.remove("selected"));button.classList.add("selected");playSound("select")}));elements.mainButton.textContent="確認答案";elements.wrongButton.textContent=state.wrongMode?"回一般刷題":"只刷錯題";elements.wrongButton.classList.toggle("hidden",state.lesson.active);updateStats()}
function renderQuestionImage(src,alt,crop){const safeSrc=escapeHtml(src),safeAlt=escapeHtml(alt),image=`<img class="question-image-object" src="${safeSrc}" alt="${safeAlt}" loading="eager" decoding="async">`;if(!crop)return image;const {sourceWidth,sourceHeight,x,y,width,height}=crop,values=[sourceWidth,sourceHeight,x,y,width,height];if(!values.every(Number.isFinite)||sourceWidth<=0||sourceHeight<=0||x<0||y<0||width<=0||height<=0||x+width>sourceWidth||y+height>sourceHeight)return image;const style=`--crop-ratio:${width/height};--source-image-width:${sourceWidth/width*100}%;--crop-left:${-x/width*100}%;--crop-top:${-y/height*100}%`;return `<div class="question-image-crop" style="${style}">${image}</div>`}
