function awardWorld(correct){if(!correct)return;state.world.sunshine+=3+(hasRelic("太陽徽章")?2:0);state.world.dew+=1+(hasBuilding("pond")?1:0)+(hasRelic("露珠背包")?2:0);const seedEvery=hasBuilding("greenhouse")||hasRelic("晶芽王冠")?8:10;if(state.history.length%seedEvery===0){state.world.seeds+=1;showReward("獲得神秘種子！",true)}if(state.history.length%15===0&&state.world.relics.length<RELICS.length){const locked=RELICS.filter(item=>!state.world.relics.includes(item));state.world.relics.push(locked[Math.floor(Math.random()*locked.length)])}}
