function startChallenge(){if(elements.startChallenge.dataset.action==="loading"){queuedChallengeStart=true;elements.startChallenge.textContent="已排入，載入後開始";elements.challengeAvailability.textContent="收到！題庫載入完成後會自動開始 10 題挑戰";return}if(elements.startChallenge.dataset.action==="retry"){loadSubject();return}if(elements.startChallenge.dataset.action==="unavailable")return;if(elements.startChallenge.dataset.action==="reset-filters"){state.difficulty="";state.unit="";state.sourceFilter="";state.wrongMode=false;elements.difficultyFilter.value="";elements.unitFilter.value="";elements.sourceFilter.value="";elements.wrongButton.setAttribute("aria-pressed","false");save();resetBagAndNext();if(challengePool().filter(item=>item.id!==state.current?.id).length>=LESSON_SIZE){elements.startChallenge.dataset.action="start";startChallenge()}return}if(state.lesson.active||elements.startChallenge.disabled)return;playSound("mission");state.wrongMode=false;state.questionBag=buildChallengeQueue();if(state.questionBag.length!==LESSON_SIZE){elements.challengeAvailability.textContent=`目前可組成 ${state.questionBag.length} / ${LESSON_SIZE} 題；題庫狀態已更新，請依上方提示操作。`;syncChallengeButton();return}state.lesson={active:true,answered:0,correct:0,xp:0,combo:0,hearts:hasRelic("木紋圓盾")?6:5,shouldEnd:false,seen:[],plannedIds:state.questionBag.map(item=>item.id)};elements.startChallenge.classList.add("hidden");document.body.classList.add("challenge-active","battle-active");elements.lessonProgress.classList.remove("hidden");setView("quiz");nextQuestion();updateStats()}
