function startExpedition(type){const trip=state.world.expedition;if(trip){if(trip.type!==type)return alert("隊伍正在另一個地點探索，請等隊伍返回。");if(Date.now()<trip.endsAt)return alert("探索隊伍還在路上，稍後再來看看！");return claimExpedition()}if(state.world.team.length<3)return alert("請先到芽靈圖鑑選滿 3 隻探索隊員");let duration=type==="ruins"?300000:120000;if(hasRelic("葉片斗篷"))duration*=.85;if(hasRelic("風翼靴"))duration*=.75;state.world.expedition={type,endsAt:Date.now()+duration};save();renderWorld()}
function speedExpedition(){const trip=state.world.expedition;if(!trip||state.world.dew<10)return alert("加速探索需要 10 露珠。");state.world.dew-=10;trip.endsAt=Math.max(Date.now(),trip.endsAt-60000);save();renderWorld();showReward("探索時間縮短 1 分鐘",true)}
