  elements.sunshineCount.textContent=state.world.sunshine;elements.dewCount.textContent=state.world.dew;elements.seedCount.textContent=state.world.seeds;elements.spiritTotal.textContent=`${total} 隻`;
  const dewCost=hasRelic("幸運澆水壺")?5:10;elements.cultivateSeed.textContent=`培育種子・60☀ ${dewCost}💧`;elements.cultivateSeed.disabled=state.world.sunshine<60||state.world.dew<dewCost;elements.hatchSeed.disabled=state.world.seeds<1;elements.hatchHint.textContent=state.world.seeds?`目前有 ${state.world.seeds} 顆種子；孵化種類依現在科目決定。`:`答題取得種子，或使用陽光與露珠主動培育。`;
  elements.gardenBuildings.innerHTML=BUILDINGS.map(item=>{const built=hasBuilding(item.id),affordable=state.world.sunshine>=item.cost;return `<div class="building ${built?"unlocked":""}"><span>${built?item.icon:"🔒"}</span><b>${item.name}</b><small>${built?item.effect:`${item.cost} 陽光・${item.effect}`}</small>${built?"":`<button data-building="${item.id}" ${affordable?"":"disabled"} aria-label="${affordable?`建造${item.name}`:`${item.name}，需要 ${item.cost} 陽光，目前有 ${state.world.sunshine} 陽光`}">${affordable?"建造":`還差 ${item.cost-state.world.sunshine} 陽光`}</button>`}</div>`}).join("");
  elements.gardenBuildings.querySelectorAll("button").forEach(button=>button.addEventListener("click",()=>buyBuilding(button.dataset.building)));
  elements.spiritGrid.innerHTML=SPECIES.map(item=>{const count=state.world.spirits[item.id]||0,selected=state.world.team.filter(id=>id===item.id).length,equipped=state.world.equipment[item.id],teamFull=state.world.team.length>=3&&selected===0;return `<article class="spirit-card ${item.color} ${count?"owned":"locked"}"><span class="spirit-icon">${item.icon}</span><div><h3>${item.name} <small>× ${count}</small></h3><p>${item.subject}系・${item.gift}${equipped?`<br>🎒 ${equipped}<span class="relic-effect">${RELIC_EFFECTS[equipped]}</span>`:""}</p></div><button data-spirit="${item.id}" ${!count||teamFull?"disabled":""} aria-label="${!count?`${item.name}尚未擁有，孵化對應芽靈種子後解鎖`:teamFull?"隊伍已滿，先移除一隻芽靈":"加入或移除隊伍中的芽靈"}">${!count?"孵化後解鎖":teamFull?"隊伍已滿":selected&&selected>=count?`移除一隻 (${selected})`:`加入隊伍 (${selected})`}</button></article>`}).join("");
