  elements.relicList.innerHTML=RELICS.map(item=>{const found=state.world.relics.includes(item);return `<button class="${found?"found":""}" data-relic="${item}" ${found?"":"disabled"}>${found?"✨":"？"} ${found?item:"未發現道具"}${found?`<span class="relic-effect">${RELIC_EFFECTS[item]}</span>`:""}</button>`}).join("");
  elements.relicList.querySelectorAll("button.found").forEach(button=>button.addEventListener("click",()=>equipRelic(button.dataset.relic)));
