function openProfile(){elements.profileName.value=state.profile.name||document.querySelector("#studentName").textContent||"";elements.profileAvatar.value=state.profile.avatar;elements.profileRole.value=state.profile.role;elements.profileSpirit.value=state.profile.spirit;elements.profileTheme.value=state.profile.theme;elements.profileGoal.value=String(state.profile.dailyGoal);elements.profileAccent.value=state.profile.accent;elements.soundEnabled.checked=state.profile.sound;elements.motionEnabled.checked=state.profile.motion;elements.hapticEnabled.checked=state.profile.haptic;elements.hapticEnabled.disabled=!navigator.vibrate;updateProfilePreview();elements.profileModal.classList.remove("hidden");playSound("nav")}
