function ensureAudio(){if(!audioContext)audioContext=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==="suspended")audioContext.resume();return audioContext}
function tone(frequency,start,duration,type="sine",gain=.05){const context=ensureAudio(),oscillator=context.createOscillator(),volume=context.createGain();if(!effectsMaster){effectsMaster=context.createGain();effectsMaster.gain.value=state.profile.volume;effectsMaster.connect(context.destination)}oscillator.type=type;oscillator.frequency.setValueAtTime(frequency,context.currentTime+start);volume.gain.setValueAtTime(.0001,context.currentTime+start);volume.gain.exponentialRampToValueAtTime(gain,context.currentTime+start+.012);volume.gain.exponentialRampToValueAtTime(.0001,context.currentTime+start+duration);oscillator.connect(volume).connect(effectsMaster);oscillator.start(context.currentTime+start);oscillator.stop(context.currentTime+start+duration+.02)}
function playSound(kind){if(!state.profile.sound)return;try{if(kind==="select")tone(330,0,.08,"triangle",.035);else if(kind==="nav")tone(240,0,.07,"sine",.025);else if(kind==="mission"){tone(220,0,.12,"triangle");tone(330,.09,.15,"triangle");tone(494,.18,.2,"triangle")}else if(kind==="correct"){tone(523,0,.12,"triangle",.07);tone(659,.08,.15,"triangle",.07);tone(784,.17,.28,"sine",.08)}else if(kind==="wrong"){tone(185,0,.16,"sine",.045);tone(147,.12,.22,"sine",.035)}else if(kind==="victory"){[392,523,659,784].forEach((note,index)=>tone(note,index*.09,.25,"triangle",.07))}else if(kind==="confirm"){tone(440,0,.1,"sine");tone(660,.08,.16,"triangle")}else if(kind==="reward"){tone(660,0,.12,"triangle");tone(880,.1,.26,"sine")}}catch{}}
function runBattleFeedback(correct,earnedXp){if(correct)burstParticles();const combo=state.lesson.active?state.lesson.combo:correct?1:0;elements.comboBadge.classList.toggle("hidden",combo<2);elements.comboBadge.querySelector("b").textContent=combo;elements.enemyShield.style.width=`${Math.max(0,100-(state.lesson.active?state.lesson.answered:1)*10)}%`;elements.battleStage.classList.remove("hit-correct","hit-wrong");void elements.battleStage.offsetWidth;elements.battleStage.classList.add(correct?"hit-correct":"hit-wrong");setTimeout(()=>elements.battleStage.classList.remove("hit-correct","hit-wrong"),950);playSound(correct?"correct":"wrong");if(state.profile.haptic&&navigator.vibrate)navigator.vibrate(correct?[25,35,45]:[55]);if(correct&&state.history.length%10===0)playSound("reward")}
function toggleSound(){const enabled=state.profile.sound||state.profile.music;state.profile.sound=!enabled;state.profile.music=!enabled;updateAudioControls();if(state.profile.music)startMusic();else stopMusic();save();if(state.profile.sound)playSound("confirm")}
