applyProfile();if(!state.profile.configured)setTimeout(openProfile,500);

function updateAudioControls(){elements.soundToggle.textContent=state.profile.sound||state.profile.music?"🔊":"🔇";elements.musicToggle.classList.toggle("off",!state.profile.music);elements.effectsToggle.classList.toggle("off",!state.profile.sound);elements.volumeControl.value=Math.round((state.profile.volume??.55)*100);elements.audioStatus.textContent=musicStarted&&state.profile.music?"Once Upon a Time・奇幻遠征配樂":"點一下頁面開啟音樂";if(bgmAudio){bgmAudio.volume=Math.min(1,(state.profile.volume??.55)*.55);bgmAudio.muted=!state.profile.music}if(effectsMaster)effectsMaster.gain.setTargetAtTime(state.profile.volume,audioContext.currentTime,.08)}
async function startMusic(){if(!state.profile.music)return;if(!bgmAudio){bgmAudio=new Audio("./assets/once-upon-a-time-loop.mp3");bgmAudio.loop=true;bgmAudio.preload="auto";bgmAudio.volume=Math.min(1,(state.profile.volume??.55)*.55)}bgmAudio.muted=false;try{await bgmAudio.play();musicStarted=true;updateAudioControls()}catch{elements.audioStatus.textContent="點一下頁面開啟音樂"}}
function stopMusic(){if(!bgmAudio)return;bgmAudio.pause();musicStarted=false;elements.audioStatus.textContent="音樂已暫停"}
function toggleMusic(){state.profile.music=!state.profile.music;if(state.profile.music)startMusic();else stopMusic();updateAudioControls();save();vibrate(10)}
function toggleEffects(){state.profile.sound=!state.profile.sound;updateAudioControls();save();if(state.profile.sound)playSound("confirm");vibrate(8)}
function setVolume(){state.profile.volume=Number(elements.volumeControl.value)/100;updateAudioControls();save()}
function vibrate(pattern){if(state.profile.haptic&&navigator.vibrate)navigator.vibrate(pattern)}
function burstParticles(){if(!state.profile.motion)return;for(let index=0;index<18;index++){const particle=document.createElement("i");particle.className="correct-burst";particle.style.left=`${65+Math.random()*20}%`;particle.style.top=`${12+Math.random()*24}%`;particle.style.setProperty("--dx",`${(Math.random()-.5)*260}px`);particle.style.setProperty("--dy",`${(Math.random()-.5)*220}px`);elements.impactLayer.append(particle);setTimeout(()=>particle.remove(),850)}}
function bindFullFeedback(){document.addEventListener("pointerdown",()=>{if(state.profile.music)startMusic()},{once:true});elements.musicToggle.addEventListener("click",toggleMusic);elements.effectsToggle.addEventListener("click",toggleEffects);elements.volumeControl.addEventListener("input",setVolume);document.querySelectorAll("button").forEach(button=>button.addEventListener("pointerenter",()=>{if(!button.disabled)playSound("nav")},{passive:true}));document.addEventListener("click",event=>{const button=event.target.closest("button");if(!button)return;if(button.matches(".world-tab,.tab,.game-action,.start-button"))vibrate(8)});updateAudioControls()}
bindFullFeedback();
function labelVisualOptionChoices(){const item=state.current;if(!item?.optionDescriptions)return;elements.options.querySelectorAll("button.option").forEach((button,index)=>{const description=item.optionDescriptions[index];if(description)button.setAttribute("aria-label",`${String.fromCharCode(65+index)}. ${description}`)})}
new MutationObserver(labelVisualOptionChoices).observe(elements.options,{childList:true});
labelVisualOptionChoices();
elements.questionImages.addEventListener("error",event=>{const image=event.target;if(!(image instanceof HTMLImageElement)||!image.classList.contains("question-image-object"))return;const fallback=document.createElement("div");fallback.className="question-image-fallback";const message=document.createElement("p");message.textContent=`圖表載入失敗：${image.alt}`;const link=document.createElement("a");link.href=image.src;link.target="_blank";link.rel="noopener";link.textContent="直接開啟圖檔";fallback.append(message,link);image.replaceWith(fallback)},true);
